import{_ as a,o as r,c as d,a5 as t}from"./chunks/framework.a5no_H3L.js";const m=JSON.parse('{"title":"RVA 与三类表：导入、导出、重定位","description":"上一章讲 PE 的头部，这一章讲「地址」和「表」。地址是 PE 格式里最容易搞混、也最影响实际分析的概念；导入表、导出表、重定位表则是理解程序行为的三张关键表。","frontmatter":{"type":"explanation","level":"intermediate"},"headers":[],"relativePath":"reverse-engineering/04-pe-format/chapter-02-address-and-tables.md","filePath":"reverse-engineering/04-pe-format/chapter-02-address-and-tables.md"}'),s={name:"reverse-engineering/04-pe-format/chapter-02-address-and-tables.md"};function n(i,e,c,o,l,p){return r(),d("div",null,[...e[0]||(e[0]=[t('<h1 id="rva-与三类表-导入、导出、重定位" tabindex="-1" data-src-line="2" data-src-file="reverse-engineering/04-pe-format/chapter-02-address-and-tables.md">RVA 与三类表：导入、导出、重定位 <a class="header-anchor" href="#rva-与三类表-导入、导出、重定位" aria-label="Permalink to &quot;RVA 与三类表：导入、导出、重定位&quot;">​</a></h1><p data-src-line="4" data-src-file="reverse-engineering/04-pe-format/chapter-02-address-and-tables.md">上一章讲 PE 的头部，这一章讲「地址」和「表」。地址是 PE 格式里最容易搞混、也最影响实际分析的概念；导入表、导出表、重定位表则是理解程序行为的三张关键表。</p><h2 id="_1-rva、va-与文件偏移" tabindex="-1" data-src-line="6" data-src-file="reverse-engineering/04-pe-format/chapter-02-address-and-tables.md">1. RVA、VA 与文件偏移 <a class="header-anchor" href="#_1-rva、va-与文件偏移" aria-label="Permalink to &quot;1. RVA、VA 与文件偏移&quot;">​</a></h2><p data-src-line="8" data-src-file="reverse-engineering/04-pe-format/chapter-02-address-and-tables.md">PE 里同时存在三套地址，必须分清：</p><ul data-src-line="10" data-src-file="reverse-engineering/04-pe-format/chapter-02-address-and-tables.md"><li data-src-line="10" data-src-file="reverse-engineering/04-pe-format/chapter-02-address-and-tables.md"><strong>文件偏移（File Offset / FOA）</strong>：数据在磁盘文件里的位置。十六进制查看器显示的就是它。</li><li data-src-line="11" data-src-file="reverse-engineering/04-pe-format/chapter-02-address-and-tables.md"><strong>RVA（Relative Virtual Address，相对虚拟地址）</strong>：数据被加载进内存后，相对 <code>ImageBase</code> 的偏移。</li><li data-src-line="12" data-src-file="reverse-engineering/04-pe-format/chapter-02-address-and-tables.md"><strong>VA（Virtual Address，虚拟地址）</strong>：<code>VA = ImageBase + RVA</code>。这是调试器、反汇编器里显示的内存地址。</li></ul><p data-src-line="14" data-src-file="reverse-engineering/04-pe-format/chapter-02-address-and-tables.md">PE 头里记录的地址几乎都是 RVA，而你在十六进制查看器里找数据用的是文件偏移。两者在文件对齐和内存对齐一致时相同，不一致时就会错位——文件里节区按 <code>FileAlignment</code>（如 <code>0x200</code>）对齐，加载进内存后按 <code>SectionAlignment</code>（如 <code>0x1000</code>）对齐，中间的差就是偏移量。</p><p data-src-line="16" data-src-file="reverse-engineering/04-pe-format/chapter-02-address-and-tables.md">换算关系：对某个 RVA <code>R</code>，先找到它落在哪个节区（该节区的 <code>VirtualAddress ≤ R &lt; VirtualAddress + VirtualSize</code>），则：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>File Offset = PointerToRawData + (R - VirtualAddress)</span></span></code></pre></div><p data-src-line="22" data-src-file="reverse-engineering/04-pe-format/chapter-02-address-and-tables.md">例如 RVA <code>0x1010</code> 落在 <code>.text</code> 节（<code>VirtualAddress = 0x1000</code>，<code>PointerToRawData = 0x400</code>），则文件偏移为 <code>0x400 + (0x1010 - 0x1000) = 0x410</code>。</p><p data-src-line="24" data-src-file="reverse-engineering/04-pe-format/chapter-02-address-and-tables.md"><strong>一个必须记住的结论：同一个数据的文件偏移和 RVA 通常不相等。</strong> 在十六进制查看器里看到一个地址，别直接拿去反汇编器里搜索，先确认它是哪种地址。反汇编器和调试器默认显示的都是 VA，PE 工具（如 PE-bear、CFF Explorer）会同时给你看文件偏移和 RVA，方便对照。</p><h2 id="_2-导入表-程序依赖谁" tabindex="-1" data-src-line="26" data-src-file="reverse-engineering/04-pe-format/chapter-02-address-and-tables.md">2. 导入表：程序依赖谁 <a class="header-anchor" href="#_2-导入表-程序依赖谁" aria-label="Permalink to &quot;2. 导入表：程序依赖谁&quot;">​</a></h2><p data-src-line="28" data-src-file="reverse-engineering/04-pe-format/chapter-02-address-and-tables.md">一个 <code>.exe</code> 几乎不可能不调用外部函数——读写文件要 <code>CreateFileW</code>，分配内存要 <code>VirtualAlloc</code>，输出要 <code>WriteFile</code>。这些函数由系统 DLL（如 <code>kernel32.dll</code>、<code>ntdll.dll</code>）提供，程序通过<strong>导入表</strong>声明自己依赖哪些 DLL 的哪些函数。</p><p data-src-line="30" data-src-file="reverse-engineering/04-pe-format/chapter-02-address-and-tables.md">导入表的结构大致是：每个被依赖的 DLL 有一个 <code>IMAGE_IMPORT_DESCRIPTOR</code>，它串起一个 <code>IMAGE_THUNK_DATA</code> 数组，逐个列出导入函数的名称（或序号）。加载器在程序启动时解析这些项，把函数的真实内存地址填入 <strong>IAT（Import Address Table，导入地址表）</strong>。</p><p data-src-line="32" data-src-file="reverse-engineering/04-pe-format/chapter-02-address-and-tables.md">对逆向的意义在于：<strong>导入表是理解程序行为的第一线索。</strong> 一个程序导入了 <code>CreateFileW</code>、<code>WriteFile</code>，大概率在读写文件；导入了 <code>RegOpenKeyExW</code>、<code>RegSetValueExW</code>，大概率在操作注册表；导入了网络相关函数，大概率要联网。静态分析的第一步，往往就是扫一眼导入表，对「这个程序想干什么」形成初步假设。</p><h2 id="_3-导出表-dll-提供什么" tabindex="-1" data-src-line="34" data-src-file="reverse-engineering/04-pe-format/chapter-02-address-and-tables.md">3. 导出表：DLL 提供什么 <a class="header-anchor" href="#_3-导出表-dll-提供什么" aria-label="Permalink to &quot;3. 导出表：DLL 提供什么&quot;">​</a></h2><p data-src-line="36" data-src-file="reverse-engineering/04-pe-format/chapter-02-address-and-tables.md"><code>.exe</code> 一般很少导出函数，导出表主要在 <code>.dll</code> 里。一个 DLL 把它愿意对外提供的函数登记在导出表里，供其他程序通过 <code>GetProcAddress</code> 查找。</p><p data-src-line="38" data-src-file="reverse-engineering/04-pe-format/chapter-02-address-and-tables.md">导出表对逆向的用处是：<strong>当你分析一个 DLL 时，导出表告诉你它对外暴露了哪些入口</strong>，这是理解该 DLL 功能的骨架。恶意软件分析里，也常通过导出函数名（如 <code>Install</code>、<code>Start</code>）快速定位核心逻辑。</p><h2 id="_4-重定位表-基址变了怎么办" tabindex="-1" data-src-line="40" data-src-file="reverse-engineering/04-pe-format/chapter-02-address-and-tables.md">4. 重定位表：基址变了怎么办 <a class="header-anchor" href="#_4-重定位表-基址变了怎么办" aria-label="Permalink to &quot;4. 重定位表：基址变了怎么办&quot;">​</a></h2><p data-src-line="42" data-src-file="reverse-engineering/04-pe-format/chapter-02-address-and-tables.md">程序编译时，链接器假设镜像会被加载到 <code>ImageBase</code> 指定的首选地址，于是把一些绝对地址直接写死在代码里。但系统可能因为地址冲突或 <strong>ASLR（地址空间布局随机化）</strong> 把它加载到别处。这时就需要<strong>重定位表</strong>：它记录「代码里哪些位置写了绝对地址」，加载器在基址变化时统一把这些位置加上偏移量，修正指针。</p><p data-src-line="44" data-src-file="reverse-engineering/04-pe-format/chapter-02-address-and-tables.md">重定位表对逆向的直接影响是：<strong>开启 ASLR 的模块，每次运行加载的基址都不同</strong>，所以你在调试器里看到的绝对地址无法跨运行复现，必须用「模块基址 + 偏移」来描述位置。反汇编器处理时会把地址显示成相对形式，避免误导。</p><hr><blockquote data-src-line="48" data-src-file="reverse-engineering/04-pe-format/chapter-02-address-and-tables.md"><p data-src-line="48" data-src-file="reverse-engineering/04-pe-format/chapter-02-address-and-tables.md">本章建立的是 PE 的地址模型和三张关键表：RVA、VA、文件偏移三套地址要能互相换算；导入表揭示程序依赖，导出表揭示 DLL 对外提供，重定位表支撑 ASLR 下的基址修正。下一章看 PE 里其余的内容——<a href="./chapter-03-tls-resource-debug.html">TLS、资源节与 Debug Directory</a>。</p></blockquote>',22)])])}const f=a(s,[["render",n]]);export{m as __pageData,f as default};
